#!/usr/bin/env node
/**
 * UniversityRT · build-css
 * Assembles source files from handbook/design-system/tokens into css/university-rt.css.
 * Order: tokens.css → _a11y.css → _button-base → all remaining components alphabetically.
 * _preview-shell.css is intentionally excluded (dev-only).
 * Autoprefixer runs on the final bundle to add vendor prefixes (-webkit-, -moz-).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import postcss from 'postcss';
import autoprefixer from 'autoprefixer';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const TOKENS = path.resolve(ROOT, '..', 'handbook', 'design-system', 'tokens');
const OUT = path.resolve(ROOT, 'css', 'university-rt.css');

const EXCLUDE = new Set(['_preview-shell.css', 'university-rt.css']);
// These files must come first, in this order.
const HEAD_ORDER = ['tokens.css', '_a11y.css'];
const COMPONENTS_DIR = path.join(TOKENS, 'components');

function read(p) {
  return fs.readFileSync(p, 'utf8').replace(/^@import\s+[^\n]+\n?/gm, '');
}
function exists(p) {
  try { fs.accessSync(p); return true; } catch { return false; }
}

function listCss(dir) {
  return fs.readdirSync(dir)
    .filter(f => f.endsWith('.css') && !EXCLUDE.has(f))
    .map(f => path.join(dir, f));
}

if (!exists(COMPONENTS_DIR)) {
  if (exists(OUT)) {
    const sizeKb = (fs.statSync(OUT).size / 1024).toFixed(1);
    console.warn(
      `Warning: tokens/components not found; keeping existing css/university-rt.css (${sizeKb} KB)`,
    );
    process.exit(0);
  }

  throw new Error(
    `Cannot build CSS: source directory not found: ${COMPONENTS_DIR}. ` +
    `Restore tokens/components or provide ${OUT}.`,
  );
}

const sections = [];

// 1. Head (tokens + a11y)
for (const name of HEAD_ORDER) {
  const p = path.join(TOKENS, name);
  if (exists(p)) sections.push({ name, body: read(p) });
}

// 2. Button base (used by Button + IconButton)
const btnBase = path.join(COMPONENTS_DIR, '_button-base.css');
if (exists(btnBase)) sections.push({ name: '_button-base.css', body: read(btnBase) });

// 3. All components alphabetically (excluding _button-base already added)
const allComponents = listCss(COMPONENTS_DIR)
  .filter(p => path.basename(p) !== '_button-base.css')
  .sort();

for (const p of allComponents) {
  sections.push({ name: path.basename(p), body: read(p) });
}

const banner = `/* =================================================================
   UniversityRT Design System · Single Bundle
   Generated by scripts/build-css.mjs · ${new Date().toISOString()}
   Source: tokens/*.css + tokens/components/*.css
   Excluded: _preview-shell.css (dev-only)
   ================================================================= */\n\n`;

const raw = banner + sections.map(s => `\n/* ─── ${s.name} ───────────────────────────────── */\n${s.body}`).join('\n');

const result = await postcss([
  autoprefixer({ overrideBrowserslist: ['> 0.5%', 'last 3 versions', 'Safari >= 9', 'iOS >= 9', 'not dead'] }),
]).process(raw, { from: undefined });

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, result.css, 'utf8');

const sizeKb = (Buffer.byteLength(result.css) / 1024).toFixed(1);
console.log(`✓ css/university-rt.css · ${sections.length} files · ${sizeKb} KB`);
